css:
.won { font-size: .62em; margin-left: .12em; }
.stack > * + * { margin-top: 0; }
.mt8{margin-top:8px}.mt12{margin-top:12px}.mt16{margin-top:16px}.mt20{margin-top:20px}.mt24{margin-top:24px}.mt28{margin-top:28px}
.mt32{margin-top:32px}.mt40{margin-top:40px}.mt48{margin-top:48px}.mt56{margin-top:56px}.mt64{margin-top:64px}
/* sky theme: cover + ad (och, ajralib turadigan) */
.sky { --bg: #E8EFF7; --fg: #0F1E3A; --muted: rgba(15,30,58,.64); --line: rgba(15,30,58,.12); --card: #FFFFFF; --blue: #0869B0; }
.sky { background: linear-gradient(180deg, #EEF3F9 0%, #E4ECF5 100%); }
.sky .kicker { color: var(--blue); }
.sky .accent { color: var(--blue); }
.sky .bottom { border-top-color: rgba(15,30,58,.12); }
.deco span { position:absolute; border-radius:50%; }
.deco .r1 { right:-370px; top:-390px; width:660px; height:660px; border:1.5px solid rgba(8,105,176,.22); }
.deco .r2 { right:-470px; top:-490px; width:860px; height:860px; border:1.5px solid rgba(8,105,176,.12); }
.cv { position:relative; }
.cover h1 { font-size: 104px; line-height: 1.04; }
.tiles { display:grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.tile { background: #FFFFFF; border: 1.5px solid rgba(8,105,176,.10); border-radius: 20px; padding: 28px 26px 26px; box-shadow: 0 1px 0 rgba(15,30,58,.04); }
.tile .num { font-size: 46px; line-height: 1; }
.tile .lbl { font: 600 22px/1.3 Manrope; color: var(--muted); margin-top: 12px; }
.swipe { font: 600 22px/1 Manrope; color: var(--muted); text-align:right; }
/* cards */
.grid2 { display:grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.card { background: var(--card); border:1.5px solid var(--line); border-radius: 22px; padding: 30px 32px; }
.card .lbl { font: 700 21px/1.2 Manrope; letter-spacing:.12em; text-transform:uppercase; color: var(--muted); }
.card .val { font: 800 40px/1.12 Sora; letter-spacing:-.02em; margin-top: 14px; }
.card .sub { font: 500 23px/1.4 Manrope; color: var(--muted); margin-top: 8px; }
.hero .num { font-size: 132px; line-height: .95; }
.hero .cap { font: 600 30px/1.35 Manrope; margin-top: 18px; }
.hero .cap span { color: var(--muted); font-weight:500; }
/* quota */
.qcols { display:grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.qcol { border:1.5px solid var(--line); border-radius: 22px; padding: 34px 32px; background: var(--card); }
.qcol .num { font-size: 112px; line-height: .95; }
.qcol .name { font: 800 30px/1.2 Sora; margin-top: 18px; letter-spacing:-.01em; }
.qcol .meta { font: 500 23px/1.4 Manrope; color: var(--muted); margin-top: 8px; }
.qcol ul { list-style:none; margin-top: 22px; border-top:1.5px solid var(--line); }
.qcol li { display:flex; justify-content:space-between; font: 600 24px/1 Manrope; padding: 15px 0; border-bottom:1.5px solid var(--line); }
.qcol li b { font-family: Sora; font-weight: 800; }
.uzbar { background: var(--navy); color: var(--paper); border-radius: 22px; padding: 30px 34px; display:flex; align-items:center; justify-content:space-between; gap: 24px; }
.uzbar .t { font: 700 21px/1 Manrope; letter-spacing:.14em; text-transform:uppercase; color: var(--gold); }
.uzbar .d { font: 500 23px/1.35 Manrope; color: rgba(242,243,239,.75); margin-top: 12px; }
.uzbar .num { font-size: 76px; line-height: 1; white-space: nowrap; }
.uzbar .num small { font: 700 28px/1 Manrope; margin-left: 8px; letter-spacing: 0; }
/* requirements */
.req { border-top:1.5px solid var(--line); }
.req .row { display:grid; grid-template-columns: 52px 190px 1fr; align-items:start; padding: 22px 0; border-bottom:1.5px solid var(--line); }
.req .k { font: 800 26px/1.3 Sora; letter-spacing:-.01em; }
.req .v { font: 500 26px/1.38 Manrope; }
.req .v span { color: var(--muted); }
.ico { width: 34px; height: 34px; border-radius: 50%; display:flex; align-items:center; justify-content:center; margin-top: 1px; }
.ico.ok { background: var(--navy); }
.ico.no { background: transparent; border: 2px solid rgba(15,30,58,.45); }
.ico svg { width: 18px; height: 18px; }
.nolist { display:grid; grid-template-columns: 1fr 1fr; gap: 14px 28px; }
.nolist div { display:grid; grid-template-columns: 46px 1fr; font: 500 24px/1.35 Manrope; align-items:start; }
.sec { font: 700 21px/1 Manrope; letter-spacing:.14em; text-transform:uppercase; color: var(--muted); }
/* procedure */
.track { border:1.5px solid var(--line); border-radius: 22px; padding: 28px 30px 30px; background: var(--card); }
.track .tname { display:flex; justify-content:space-between; align-items:baseline; }
.track .tname b { font: 800 28px/1 Sora; letter-spacing:-.01em; }
.track .tname span { font: 600 21px/1 Manrope; color: var(--muted); }
.steps { display:flex; align-items:center; margin-top: 26px; }
.step { flex: 1; text-align:center; }
.step .dot { width: 64px; height: 64px; border-radius: 50%; margin: 0 auto; display:flex; align-items:center; justify-content:center;
font: 800 26px/1 Sora; border: 2px solid var(--navy); color: var(--navy); background: var(--paper); }
.step.end .dot { background: var(--navy); color: var(--paper); }
.step .sl { font: 700 22px/1.25 Manrope; margin-top: 14px; }
.step .ss { font: 500 19px/1.3 Manrope; color: var(--muted); margin-top: 4px; }
.arrow { flex: none; width: 46px; height: 2px; background: rgba(15,30,58,.25); margin-top: -62px; position:relative; }
.arrow:after { content:""; position:absolute; right:-1px; top:-5px; border-left: 10px solid rgba(15,30,58,.35); border-top:6px solid transparent; border-bottom:6px solid transparent; }
.chips { display:flex; flex-wrap:wrap; gap: 12px; }
.chip { font: 600 23px/1 Manrope; padding: 15px 22px; border-radius: 999px; border:1.5px solid var(--line); background: var(--card); }
.bonus { display:grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.bonus > div { border-left: 4px solid var(--gold); padding: 6px 0 6px 22px; }
.bonus .num { font-size: 52px; line-height: 1; }
.bonus .bl { font: 600 23px/1.35 Manrope; color: var(--muted); margin-top: 8px; }
/* timeline */
.tl { position:relative; margin-left: 10px; }
.tl:before { content:""; position:absolute; left: 11px; top: 40px; bottom: 40px; width: 2px; background: var(--line); }
.tl .it { display:grid; grid-template-columns: 56px 280px 1fr; align-items:center; padding: 24px 0; position:relative; }
.tl .pt { width: 24px; height: 24px; border-radius: 50%; background: var(--paper); border: 3px solid var(--navy); position:relative; z-index:1; }
.tl .it.done .pt { background: rgba(15,30,58,.25); border-color: rgba(15,30,58,.25); }
.tl .it.final .pt { background: var(--gold); border-color: var(--gold); }
.tl .dt { font: 800 30px/1.2 Sora; letter-spacing:-.01em; }
.tl .ev { font: 500 28px/1.35 Manrope; }
.tl .it.done .dt, .tl .it.done .ev { color: var(--muted); }
.badge { display:inline-block; font: 700 17px/1 Manrope; letter-spacing:.1em; text-transform:uppercase; padding: 8px 12px; border-radius: 8px;
background: rgba(15,30,58,.08); color: var(--muted); margin-left: 12px; vertical-align: 4px; }
.note { background: var(--navy); color: var(--paper); border-radius: 22px; padding: 30px 34px; }
.note .t { font: 800 28px/1.2 Sora; }
.note .d { font: 500 24px/1.42 Manrope; color: rgba(242,243,239,.78); margin-top: 10px; }
/* tips */
.tips .tip { display:grid; grid-template-columns: 96px 1fr; padding: 24px 0; border-bottom: 1.5px solid var(--line); align-items:baseline; }
.tips .tip:first-child { border-top: 1.5px solid var(--line); }
.tips .n { font: 800 34px/1 Sora; color: #9A7A2E; letter-spacing:-.02em; }
.tips .h { font: 800 31px/1.2 Sora; letter-spacing:-.015em; }
.tips .p { font: 500 25px/1.4 Manrope; color: var(--muted); margin-top: 8px; }
/* cta */
.cta h1 { font-size: 94px; }
.services { display:grid; grid-template-columns: 1fr 1fr; gap: 0 28px; border-top:1.5px solid var(--line); }
.services div { font: 600 26px/1.2 Manrope; padding: 20px 0; border-bottom:1.5px solid var(--line); display:flex; gap:16px; align-items:center; }
.services div:before { content:""; width: 10px; height: 10px; background: var(--blue); border-radius: 2px; flex:none; }
.ccard { background: #FFFFFF; border: 1.5px solid rgba(8,105,176,.10); border-radius: 22px; padding: 8px 32px; }
.ccard .c { display:grid; grid-template-columns: 170px 1fr; align-items:baseline; padding: 22px 0; border-bottom: 1.5px solid var(--line); }
.ccard .c:last-child { border-bottom: 0; }
.ccard .c span { font: 700 19px/1 Manrope; letter-spacing:.14em; text-transform:uppercase; color: var(--muted); }
.ccard .c b { font: 700 30px/1.2 Manrope; }
.ccard .c em { font: 500 23px/1.2 Manrope; font-style: normal; color: var(--muted); margin-left: 10px; }
.btn { display:inline-flex; align-items:center; gap: 14px; background: var(--blue); color: #FFFFFF; font: 800 28px/1 Manrope; padding: 26px 40px; border-radius: 999px; }
